  { name: 'Emeka Okonkwo', age: '58', gender: 'Male', bloodType: 'B+', allergies: 'Sulfa', medications: 'Metformin, Atorvastatin', conditions: 'Type 2 Diabetes, High Cholesterol', lastVisit: '2026-05-22', nextAppt: '2026-09-15', phone: '+2348034567890', urgency: 'high', notes: 'Monitor blood sugar' },
