];

const query = $('Extract Query').item.json.query.toLowerCase().trim();

if (!query) {
  return [{ json: { error: 'No search query provided', found: false } }];
}

const match = patients.find(p => p.name.toLowerCase().includes(query));

if (!match) {
  return [{ json: { error: 'Patient not found. Try a different name.', found: false } }];
}

return [{ json: { ...match, found: true } }];
